using LabMaster.Data; using LabMaster.Models; using Microsoft.Data.SqlClient;
namespace LabMaster.Services;
public sealed class PatientService { public async Task<string> GetNextMrNumberAsync(){ await using var c=Database.CreateConnection(); await c.OpenAsync(); await using var cmd=new SqlCommand("SELECT ISNULL(MAX(PatientId),0)+1 FROM dbo.Patients",c); return $"MR-{Convert.ToInt32(await cmd.ExecuteScalarAsync()):000000}"; } public async Task<int> SaveAsync(Patient p){ await using var c=Database.CreateConnection(); await c.OpenAsync(); const string sql="INSERT INTO dbo.Patients(MRNumber,PatientName,FatherName,Gender,Phone,Address,ReferringDoctor) OUTPUT INSERTED.PatientId VALUES(@MR,@Name,@Father,@Gender,@Phone,@Address,@Doctor)"; await using var cmd=new SqlCommand(sql,c); cmd.Parameters.AddWithValue("@MR",p.MRNumber); cmd.Parameters.AddWithValue("@Name",p.PatientName); cmd.Parameters.AddWithValue("@Father",(object?)p.FatherName??DBNull.Value); cmd.Parameters.AddWithValue("@Gender",p.Gender); cmd.Parameters.AddWithValue("@Phone",(object?)p.Phone??DBNull.Value); cmd.Parameters.AddWithValue("@Address",(object?)p.Address??DBNull.Value); cmd.Parameters.AddWithValue("@Doctor",(object?)p.ReferringDoctor??DBNull.Value); return Convert.ToInt32(await cmd.ExecuteScalarAsync()); } }